import * as THREE from './assets/three.module.js';
import {getPosition,getTimes} from './assets/suncalc.js';
import {cities,periods,periodAt,artUrl} from './catalog.js';
import {parts,offset,previewInstant,pad} from './time-utils.js';
import {Illustration} from './illustration.js';
import {makeCity3D} from './scene3d.js';
import {installImmersive} from './immersive.js';
const $=id=>document.getElementById(id),reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
let motion=!reduceMotion.matches,preview=null,previewCity='taipei',touring=false,tourStart=0,tourMinute=0,lastFrame=0,lastTourMinute=-1,immersive=false;
const models={},art={},modes={paris:'3d',taipei:'art'},activePeriods={};
try{const saved=JSON.parse(localStorage.getItem('quiet-hours.v2.modes'));for(const city of Object.keys(cities))if(['art','3d','live'].includes(saved?.[city]))modes[city]=saved[city];}catch{}
function card(city){const c=cities[city];return `<article class="city-card ${city}" id="${city}-card"><div class="scene" id="${city}-scene"><canvas class="model-canvas" id="${city}-canvas" aria-label="${c.name} 3D 城市日照場景"></canvas><div class="illustration-layer" id="${city}-illustration"><canvas class="art-canvas" id="${city}-art-canvas" aria-label="${c.name} 分時段動態插畫"></canvas><div class="cloud cloud-a"></div><div class="cloud cloud-b"></div></div><div class="scene-error" id="${city}-art-error" hidden><p>這幅插畫暫時未能載入</p><span>可以切換 3D 或稍後再試。</span><button class="quiet-button" data-retry="${city}">重新載入 ↻</button></div><div class="scene-error" id="${city}-fallback" hidden><p>此裝置無法顯示 3D</p><span>請切換 2D 插畫繼續觀看。</span></div><div class="scene-vignette"></div><div class="scene-top"><span class="scene-kind" id="${city}-kind">分時段插畫</span><span class="sun-label" id="${city}-light">計算中</span></div><div class="scene-caption"><span>${c.tagline}</span><p>${c.caption}</p></div><span class="period-caption" id="${city}-period"></span><div class="live-panel" id="${city}-live" hidden><span class="live-status">公開影像 · 外連觀看</span><p class="eyebrow">A WINDOW TO THE REAL WORLD</p><h3>看看此刻的${c.name}</h3><p>${c.live.name}<br>前往來源網站，觀看當地真實影像。</p><a href="${c.live.url}" target="_blank" rel="noopener noreferrer">開啟公開攝影機 ↗</a><small>影像可用性與延遲依來源網站為準</small></div></div><div class="city-details"><div class="place-line"><div class="place-name"><div class="mini-clock" aria-hidden="true"><i class="hand hour-hand" id="${city}-hour-hand"></i><i class="hand minute-hand" id="${city}-minute-hand"></i></div><div><span class="country">${c.country}</span><h2>${c.name} <span>${c.english}</span></h2></div></div><div class="mode-switch" aria-label="${c.name}顯示模式"><button data-city="${city}" data-mode="live" aria-pressed="false">Live View ↗</button><button data-city="${city}" data-mode="art" aria-pressed="false">2D 插畫</button><button data-city="${city}" data-mode="3d" aria-pressed="false">3D 動畫</button></div></div><div class="time-line"><time id="${city}-time">--:--</time><span class="seconds" id="${city}-seconds">--</span><span class="zone">${c.zone.replace('/',' / ')}</span></div><div class="city-meta"><span id="${city}-date">—</span><span id="${city}-solar">—</span></div><p class="mode-note" id="${city}-note"></p></div></article>`;}
$('worlds').innerHTML=card('paris')+'<div class="between"><span class="between-line"></span><span id="difference">+7h</span><button id="swap" aria-label="交換兩地位置" title="交換兩地位置">⇄</button><span class="between-line"></span></div>'+card('taipei');
const immersiveClocks=installImmersive(cities);
const current=()=>preview===null?new Date():new Date(preview);
function solarState(date,c){const sun=getPosition(date,c.lat,c.lon);return {sun,day:THREE.MathUtils.smoothstep(sun.altitude,-7,9),gold:1-THREE.MathUtils.smoothstep(Math.abs(sun.altitude-2),0,20),label:sun.altitude>8?'日光':sun.altitude>0?'金色時刻':sun.altitude>-7?'暮光':'夜色'};}
function solarTime(value,zone){return value instanceof Date&&!isNaN(value)?new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(value):'—';}
function updateTime(){const date=current();for(const [city,c]of Object.entries(cities)){const p=parts(date,c.zone),period=periodAt(p.hour),sun=solarState(date,c),times=getTimes(previewInstant(720,c.zone,date),c.lat,c.lon);immersiveClocks.update(city,p);$(city+'-time').textContent=`${pad(p.hour)}:${pad(p.minute)}`;$(city+'-time').dateTime=date.toISOString();$(city+'-seconds').textContent=pad(p.second);$(city+'-date').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:c.zone,month:'long',day:'numeric',weekday:'short'}).format(date);$(city+'-solar').textContent=`↑ ${solarTime(times.sunrise,c.zone)}　↓ ${solarTime(times.sunset,c.zone)}`;$(city+'-hour-hand').style.transform=`rotate(${p.hour*30+p.minute*.5}deg)`;$(city+'-minute-hand').style.transform=`rotate(${p.minute*6}deg)`;$(city+'-period').textContent=modes[city]==='live'?'':`${period.icon} ${period.name}`;$(city+'-light').textContent=modes[city]==='art'?`${period.icon} ${period.name}`:`☼ ${sun.label}`;
if(activePeriods[city]!==period.key){activePeriods[city]=period.key;art[city]?.load(artUrl(city,period),motion);$(city+'-art-canvas').setAttribute('aria-label',`${c.name} ${period.name}動態插畫，水面緩慢流動`);}if(modes[city]==='3d')models[city]?.light(date,sun);}
const first=$('worlds').firstElementChild.id==='paris-card'?1:-1,difference=first*(offset(date,cities.taipei.zone)-offset(date,cities.paris.zone))/60;$('difference').textContent=`${difference>=0?'+':''}${difference}h`;
const p=parts(date,cities[previewCity].zone);$('preview-time').textContent=`${pad(p.hour)}:${pad(p.minute)}`;$('time-slider').value=p.hour*60+p.minute;
const status=preview===null?'跟隨當下 · 兩地同步':touring?'一天光影漫遊 · 加速預覽':'時間預覽中 · 兩地同步';if($('preview-status').textContent!==status)$('preview-status').textContent=status;
const active=periodAt(p.hour).key;document.querySelectorAll('[data-period]').forEach(b=>{const selected=b.dataset.period===active;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});}
function setMode(city,mode,persist=true){modes[city]=mode;$(city+'-live').hidden=mode!=='live';$(city+'-illustration').hidden=mode!=='art';$(city+'-canvas').hidden=mode!=='3d';$(city+'-kind').textContent=mode==='art'?'2D / 分時段插畫':mode==='3d'?'3D / 立體光景':'LIVE / 真實城市';$(city+'-note').textContent=mode==='art'?'八幅時段插畫 · 水面局部循環':mode==='3d'?'日照隨當地時間變化 · 非即時天氣':'來源可內嵌時優先內嵌；目前提供外連觀看。';document.querySelectorAll(`[data-city="${city}"][data-mode]`).forEach(b=>{const on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
if(art[city])art[city].visible=mode==='art';if(mode==='3d'&&!models[city]){try{models[city]=makeCity3D(city);}catch(error){console.error('3D initialization failed',city,error);$(city+'-fallback').hidden=false;}}$(city+'-fallback').hidden=mode!=='3d'||!!models[city];models[city]?.setVisible(mode==='3d');if(mode!=='art')$(city+'-art-error').hidden=true;else $(city+'-art-error').hidden=!art[city]?.failed;
if(persist)try{localStorage.setItem('quiet-hours.v2.modes',JSON.stringify(modes));}catch{}updateTime();art[city]?.render(performance.now()/1000,motion);}
function library(){const c=cities[previewCity];$('library-title').textContent=`${c.name}的一天，八種溫柔。`;$('period-grid').innerHTML=periods.map(p=>`<button class="period-tile" data-period="${p.key}" aria-label="預覽${c.name}${p.name}插畫" aria-pressed="false"><img src="${artUrl(previewCity,p)}" alt="${c.name}${p.name}插畫縮圖" loading="lazy"><span class="tile-label">${p.name}<span>${p.icon}</span></span><small>${pad(p.start)}:00–${pad(p.end)}:00</small></button>`).join('');document.querySelectorAll('[data-period]').forEach(button=>button.addEventListener('click',()=>{stopTour();const period=periods.find(p=>p.key===button.dataset.period);preview=+previewInstant(period.start*60+30,cities[previewCity].zone);setMode(previewCity,'art');updateTime();}));}
function stopTour(){touring=false;$('day-play').textContent='▷ 光影漫遊';$('day-play').setAttribute('aria-pressed','false');}
function applyMotion(){document.body.classList.toggle('still',!motion);$('motion').textContent=motion?'◌ 動態開啟':'◯ 靜態模式';$('motion').setAttribute('aria-pressed',String(motion));if(!motion)stopTour();updateTime();for(const illustration of Object.values(art))illustration.render(performance.now()/1000,motion);}
for(const [city,c]of Object.entries(cities)){art[city]=new Illustration(city,$(city+'-art-canvas'),c.water);$(city+'-art-canvas').addEventListener('art-error',()=>{$(city+'-art-error').hidden=modes[city]!=='art';});}
for(const city of Object.keys(cities))setMode(city,modes[city],false);
$('motion').addEventListener('click',()=>{motion=!motion;applyMotion();});reduceMotion.addEventListener('change',()=>{motion=!reduceMotion.matches;applyMotion();});
$('time-slider').addEventListener('input',e=>{stopTour();preview=+previewInstant(Number(e.target.value),cities[previewCity].zone);updateTime();});
$('preview-city').addEventListener('change',e=>{stopTour();previewCity=e.target.value;library();updateTime();});
$('reset').addEventListener('click',()=>{stopTour();preview=null;updateTime();});
$('day-play').addEventListener('click',()=>{if(touring){stopTour();updateTime();return;}motion=true;applyMotion();touring=true;tourMinute=Number($('time-slider').value);tourStart=performance.now();lastTourMinute=-1;$('day-play').textContent='Ⅱ 暫停漫遊';$('day-play').setAttribute('aria-pressed','true');});
$('swap').addEventListener('click',()=>{const worlds=$('worlds'),first=worlds.firstElementChild,last=worlds.lastElementChild;worlds.insertBefore(last,first);worlds.appendChild(first);updateTime();});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.city,b.dataset.mode)));
document.querySelectorAll('[data-retry]').forEach(b=>b.addEventListener('click',()=>{const city=b.dataset.retry;art[city].url=null;art[city].load(artUrl(city,periodAt(parts(current(),cities[city].zone).hour)),motion);$(city+'-art-error').hidden=true;}));
library();applyMotion();setInterval(()=>{if(!touring&&!document.hidden)updateTime();},1000);
function frame(t){requestAnimationFrame(frame);if(document.hidden||t-lastFrame<1000/24)return;lastFrame=t;if(touring){const elapsed=(t-tourStart)/1000,minute=Math.floor((tourMinute+elapsed*24)%1440);if(minute!==lastTourMinute){lastTourMinute=minute;preview=+previewInstant(minute,cities[previewCity].zone);updateTime();}if(elapsed>=60){stopTour();updateTime();}}if(motion){for(const [city,model]of Object.entries(models))if(modes[city]==='3d')model?.animate(t/1000);for(const [city,illustration]of Object.entries(art))if(modes[city]==='art')illustration.render(t/1000,true);}}
requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour();else updateTime();});


